# frozen_string_literal: true

require "tinygql/executable_parser"
require "tinygql/scalars"
require "tinygql/inputs"
require "tinygql/executor"
require "set"

module TinyGQL
  # Base class for parsers generated by TinyGQL::Generator.  Generated
  # subclasses parse executable documents and validate them against the
  # schema they were generated from.
  #
  # Scalar literals are checked with `scalars`, which defaults to an instance
  # of the generated parser's Scalars class.  See TinyGQL::Scalars.
  class ValidatingParser < ExecutableParser
    # @rbs @doc: String
    # @rbs @scalars: Scalars
    # @rbs @fragments: Hash[String, String]
    # @rbs @spreads: Array[Nodes::FragmentSpread | String]
    # @rbs @operations: Array[Scope]
    # @rbs @fragment_scopes: Hash[String, Scope]
    # @rbs @operation_names: Set[String]
    # @rbs @scope: Scope
    # @rbs @merged: Hash[Nodes::Field, Hash[Nodes::Field, bool]]
    # @rbs @collected: Hash[Array[Nodes::Field | Nodes::InlineFragment | Nodes::FragmentSpread], Hash[String, Nodes::Field | Array[Nodes::Field]]]

    class ValidationError < StandardError; end

    # The variables an operation or fragment defines and uses.  Variables
    # are numbered by name across the document, so `defined` and `used` are
    # bitmaps of those numbers.  The arrays are indexed by number:
    #
    #   definitions: each VariableDefinition, for operations
    #   first_use: the first Variable node for each variable, for errors
    #   types: a Hash from each type node a variable is used as, to the
    #     first Variable node used as that type
    #
    # Checking an operation merges in the fragments it spreads, directly or
    # through other fragments.  `state` is :closing while that happens, and
    # :closed once a fragment's scope includes everything it spreads, so
    # each fragment is only merged once
    class Scope
      attr_accessor :node #: (Nodes::OperationDefinition | Nodes::FragmentDefinition)?
      attr_reader :definitions #: Array[Nodes::VariableDefinition?]
      attr_accessor :defined #: Integer
      attr_accessor :used #: Integer
      attr_reader :first_use #: Array[Nodes::Variable?]
      attr_reader :types #: Array[Hash[Nodes::NamedType | Nodes::ListType | Nodes::NotNullType, Nodes::Variable]?]
      attr_reader :spreads #: Array[Nodes::FragmentSpread]
      attr_accessor :state #: (:closing | :closed)?

      #: () -> void
      def initialize
        @node = nil
        @definitions = []
        @defined = 0
        @used = 0
        @first_use = []
        @types = []
        @spreads = []
        @state = nil
      end
    end

    #: (String, ?scalars: Scalars) -> Nodes::Document
    def self.parse doc, scalars: self::Scalars.new
      new(doc, scalars: scalars).parse
    end

    # Coerces the JSON `variables` of a request that runs operation `op` in
    # `doc`, a document this parser parsed.  `op` may be nil when `doc` has
    # one operation.  Returns a frozen Array indexed by Variable#index, or
    # raises TinyGQL::Inputs::Error.  See TinyGQL::Inputs
    #: (Nodes::Document, untyped, ?op: String?, ?scalars: Scalars) -> Array[untyped]
    def self.coerce doc, variables, op: nil, scalars: self::Scalars.new
      self::Inputs.new(scalars).coerce(doc, variables, op)
    end

    # Executes operation `op` in `doc`, a document this parser parsed, and
    # returns the response.  `variables` come from `coerce`, and `root` is
    # the object of the operation's root type.  See TinyGQL::Executor
    #: (Nodes::Document, Array[untyped], resolvers: untyped, ?op: String?, ?root: untyped, ?context: untyped, ?scalars: Scalars) -> Hash[String, untyped]
    def self.execute doc, variables, resolvers:, op: nil, root: nil, context: nil, scalars: self::Scalars.new
      self::Executor.new(resolvers, scalars, self::Inputs.new(scalars), variables, context).execute(doc, op, root)
    end

    #: (String, ?scalars: Scalars) -> void
    def initialize doc, scalars: self.class::Scalars.new
      super(doc)
      @doc = doc
      @scalars = scalars
      @fragments = {}
      @spreads = []
      @operations = []
      @fragment_scopes = {}
      @operation_names = Set.new
      # The scope of the operation or fragment being parsed
      @scope = nil
      # Pairs of fields already checked for merging, and whether they were
      # checked as mutually exclusive
      @merged = {}.compare_by_identity
      # The fields in each selection set, by response key.  Keys with one
      # field have the field, and keys with more have an Array of them
      @collected = {}.compare_by_identity
    end

    #: () -> Nodes::Document
    def parse
      doc = super
      check_anonymous_operations
      check_fragment_spreads
      check_variables
      check_fragments_used
      check_field_merging
      doc
    end

    private

    #: () -> Nodes::OperationDefinition
    def operation_definition
      scope = @scope = new_scope
      operation = super
      scope.node = operation
      @operations << scope
      if (name = operation.name)
        validation_error!("Duplicate operation #{name}", operation.start) unless @operation_names.add?(name)
      end
      operation
    end

    #: () -> Nodes::FragmentDefinition
    def fragment_definition
      scope = @scope = new_scope
      fragment = super
      scope.node = fragment
      @fragment_scopes[fragment.fragment_name] = scope
      fragment
    end

    #: () -> Scope
    def new_scope
      Scope.new
    end


    #: () -> Nodes::VariableDefinition
    def variable_definition
      loc = pos
      var_loc = pos
      expect_token :VAR_SIGN
      name = self.name
      id = variable_id(name)
      var = Nodes::Variable.new(var_loc, name, id)
      if @scope.definitions[id]
        validation_error! "Duplicate variable $#{name}", var_loc
      end
      expect_token :COLON
      type_loc = pos
      type = self.type
      named = type
      named = named.type until named.named_type?
      unless input_type?(named.name)
        validation_error! "Variable $#{var.name} cannot be of non-input type #{type_string(type)}", type_loc
      end
      default_value = if at?(:EQUALS)
        accept_token
        default_loc = pos
        begin
          typed_value type
        rescue Scalars::InvalidValue => e
          validation_error! "Invalid default value for $#{var.name}: #{e.message}", default_loc
        end
      end
      directives = if at?(:DIR_SIGN); self.directives; end

      definition = Nodes::VariableDefinition.new(loc, var, type, default_value, directives)
      @scope.definitions[id] = definition
      @scope.defined |= 1 << id
      definition
    end

    # Parses a value of `type`, a type node from a variable definition.
    # Variables may be declared with any wrapping of an input type, so this
    # walks the wrappers and parses the named type with named_value
    #: (Nodes::NamedType | Nodes::ListType | Nodes::NotNullType) -> (Nodes::Value | Nodes::ObjectValue | Nodes::Variable)
    def typed_value type
      if type.not_null_type?
        null_value! type_string(type) if at?(:NULL)
        typed_value type.type
      elsif type.list_type?
        case token_name
        when :NULL then null_value
        when :LBRACKET
          loc = pos
          accept_token
          items = []
          items << typed_value(type.type) while !at?(:RBRACKET)
          accept_token
          Nodes::ListValue.new(loc, items.freeze, nil)
        else
          # A single value where a list is expected is a list of one
          typed_value type.type
        end
      else
        named_value type.name
      end
    end

    # A variable where the schema doesn't say what type is expected, like
    # in a directive argument
    #: () -> Nodes::Variable
    def variable
      variable_usage nil, false
    end

    # A variable used where a value of `type`, a type node, is expected.
    # Usages are checked against the operations' variable definitions once
    # the whole document is parsed.  Type nodes come from constants in the
    # generated parser, so a variable used as the same type many times is
    # only recorded and checked once.  Constant values, like variable
    # defaults, can't use variables
    #: ((Nodes::NamedType | Nodes::ListType | Nodes::NotNullType)?, bool) -> Nodes::Variable
    def variable_usage type, const
      if const
        raise Scalars::InvalidValue, "Variables can't be used in default values"
      end
      loc = pos
      expect_token :VAR_SIGN
      name = self.name
      id = variable_id(name)
      var = Nodes::Variable.new(loc, name, id)
      scope = @scope
      scope.used |= 1 << id
      scope.first_use[id] ||= var
      if type
        types = scope.types[id] ||= {}.compare_by_identity
        types[type] ||= var
      end
      var
    end

    #: (String, Nodes::TypeCondition) -> Array[Nodes::Field | Nodes::InlineFragment | Nodes::FragmentSpread]
    def fragment_selection_set name, type_condition
      if @fragments.key?(name)
        validation_error! "Duplicate fragment #{name}", type_condition.start
      end
      type = type_condition.named_type.name
      @fragments[name] = type
      composite_selection_set type, type_condition.start
    end

    # Parses a fragment spread or inline fragment inside a selection set on
    # `parent`
    #: (String) -> (Nodes::InlineFragment | Nodes::FragmentSpread)
    def schema_selection_fragment parent
      expect_token :ELLIPSIS

      case token_name
      when :ON, :DIR_SIGN, :LCURLY
        loc = pos
        type_condition = if at?(:ON); self.type_condition; end
        directives = if at?(:DIR_SIGN); self.directives; end

        type = if type_condition
          type = type_condition.named_type.name
          check_spread type, parent, type_condition.start
          type
        else
          parent
        end

        Nodes::InlineFragment.new(loc, type_condition, directives, composite_selection_set(type, loc))
      else
        spread = fragment_spread
        # Fragments may be defined after they're used, so check these once
        # the whole document is parsed
        @spreads << spread << parent
        @scope.spreads << spread
        spread
      end
    end

    #: () -> void
    def check_fragment_spreads
      i = 0
      while i < @spreads.length
        spread = @spreads[i]
        parent = @spreads[i + 1]
        type = @fragments[spread.fragment_name]
        unless type
          validation_error! "Unknown fragment #{spread.fragment_name}", spread.start
        end
        check_spread type, parent, spread.start
        i += 2
      end
    end

    # Anonymous operations are only allowed alone, because requests pick
    # operations by name
    #: () -> void
    def check_anonymous_operations
      return if @operations.length < 2
      i = 0
      while i < @operations.length
        operation = @operations[i].node
        unless operation.name
          validation_error! "An anonymous operation must be the only operation in the document", operation.start
        end
        i += 1
      end
    end

    # Checks each operation's variables, including the ones used by the
    # fragments it spreads.  Fragments are closed first, so cycles are found
    # even in fragments no operation uses
    #: () -> void
    def check_variables
      fragments = @fragment_scopes.values
      i = 0
      while i < fragments.length
        close_scope fragments[i] unless fragments[i].state
        i += 1
      end

      i = 0
      while i < @operations.length
        scope = @operations[i]
        close_scope scope
        check_scope scope
        i += 1
      end
    end

    # Merges the scopes of the fragments `scope` spreads into it, closing
    # them first
    #: (Scope) -> void
    def close_scope scope
      scope.state = :closing
      spreads = scope.spreads
      i = 0
      while i < spreads.length
        spread = spreads[i]
        fragment = @fragment_scopes[spread.fragment_name]
        case fragment.state
        when :closing
          validation_error! "Fragment #{spread.fragment_name} spreads itself", spread.start
        when nil
          close_scope fragment
        end
        merge_scope scope, fragment
        i += 1
      end
      scope.state = :closed
    end

    #: (Scope, Scope) -> void
    def merge_scope scope, other
      scope.used |= other.used

      first_use = other.first_use
      i = 0
      while i < first_use.length
        scope.first_use[i] ||= first_use[i]
        i += 1
      end

      types = other.types
      i = 0
      while i < types.length
        if (others = types[i])
          mine = scope.types[i] ||= {}.compare_by_identity
          keys = others.keys
          j = 0
          while j < keys.length
            mine[keys[j]] ||= others[keys[j]]
            j += 1
          end
        end
        i += 1
      end
    end

    # Checks a closed operation scope
    #: (Scope) -> void
    def check_scope scope
      operation = scope.node

      undefined = scope.used & ~scope.defined
      if undefined != 0
        var = scope.first_use[lowest_bit(undefined)]
        validation_error! "Variable $#{var.name} is not defined#{operation_label(operation)}", var.start
      end

      unused = scope.defined & ~scope.used
      if unused != 0
        var = scope.definitions[lowest_bit(unused)].variable
        validation_error! "Variable $#{var.name} is never used#{operation_label(operation)}", var.start
      end

      types = scope.types
      id = 0
      while id < types.length
        if (locations = types[id])
          definition = scope.definitions[id]
          keys = locations.keys
          j = 0
          while j < keys.length
            location = keys[j]
            unless variable_allowed?(definition, location)
              var = locations[location]
              validation_error! "Variable $#{var.name} of type #{type_string(definition.type)} used in position expecting #{type_string(location)}", var.start
            end
            j += 1
          end
        end
        id += 1
      end
    end

    # Every fragment must be spread by some operation, directly or through
    # other fragments.  Runs after check_variables, which rejects fragments
    # that spread themselves, and after check_fragment_spreads, so every
    # spread names a fragment
    #: () -> void
    def check_fragments_used
      return if @fragment_scopes.empty?

      used = {}
      pending = []
      i = 0
      while i < @operations.length
        pending.concat @operations[i].spreads
        i += 1
      end
      while (spread = pending.pop)
        name = spread.fragment_name
        next if used.key?(name)

        used[name] = true
        pending.concat @fragment_scopes[name].spreads
      end
      return if used.length == @fragment_scopes.length

      fragments = @fragment_scopes.values
      i = 0
      while i < fragments.length
        fragment = fragments[i].node
        unless used.key?(fragment.fragment_name)
          validation_error! "Fragment #{fragment.fragment_name} is never used", fragment.start
        end
        i += 1
      end
    end

    # Checks that the fields with the same response key in each selection
    # set can be merged into one, as the spec's "Field Selection Merging"
    # describes.  Fragments are checked once each, where they're defined,
    # and their fields are merged into the selection sets that spread them.
    # Runs after check_variables, which rejects fragments that spread
    # themselves
    #: () -> void
    def check_field_merging
      i = 0
      while i < @operations.length
        check_selection_sets @operations[i].node.selection_set
        i += 1
      end
      fragments = @fragment_scopes.values
      i = 0
      while i < fragments.length
        check_selection_sets fragments[i].node.selection_set
        i += 1
      end
    end

    # Checks `selections` and every selection set inside it
    #: (Array[Nodes::Field | Nodes::InlineFragment | Nodes::FragmentSpread]) -> void
    def check_selection_sets selections
      fields = merged_fields(selections)
      keys = fields.keys
      i = 0
      while i < keys.length
        same_key = fields[keys[i]]
        if same_key.is_a?(Array)
          j = 0
          while j < same_key.length
            k = j + 1
            while k < same_key.length
              check_merge same_key[j], same_key[k], false
              k += 1
            end
            j += 1
          end
        end
        i += 1
      end

      i = 0
      while i < selections.length
        selection = selections[i]
        if selection.field?
          set = selection.selection_set
          check_selection_sets set if set
        elsif selection.inline_fragment?
          check_selection_sets selection.selection_set
        end
        i += 1
      end
    end

    # The fields in `selections` by response key, including the fields of
    # fragments
    #: (Array[Nodes::Field | Nodes::InlineFragment | Nodes::FragmentSpread]) -> Hash[String, Nodes::Field | Array[Nodes::Field]]
    def merged_fields selections
      fields = @collected[selections]
      unless fields
        fields = @collected[selections] = {}
        collect_merged_fields selections, fields, nil
      end
      fields
    end

    # Adds the fields in `selections` to `fields` by response key, including
    # the fields of fragments.  `spread` has the fragments already added,
    # and is nil until there are some
    #: (Array[Nodes::Field | Nodes::InlineFragment | Nodes::FragmentSpread], Hash[String, Nodes::Field | Array[Nodes::Field]], Hash[String, true]?) -> Hash[String, true]?
    def collect_merged_fields selections, fields, spread
      i = 0
      while i < selections.length
        selection = selections[i]
        if selection.field?
          key = selection.aliaz || selection.name
          same_key = fields[key]
          if same_key.nil?
            fields[key] = selection
          elsif same_key.is_a?(Array)
            same_key << selection
          else
            fields[key] = [same_key, selection]
          end
        elsif selection.inline_fragment?
          spread = collect_merged_fields(selection.selection_set, fields, spread)
        else
          name = selection.fragment_name
          spread ||= {}
          unless spread.key?(name)
            spread[name] = true
            spread = collect_merged_fields(@fragment_scopes[name].node.selection_set, fields, spread)
          end
        end
        i += 1
      end
      spread
    end

    # Checks that fields `a` and `b`, which have the same response key, can
    # be merged.  They're mutually exclusive when they're on different
    # object types, or inside fields that are, so only one of them can be
    # in the response.  Exclusive fields may differ in name and arguments,
    # but must still have the same response shape
    #: (Nodes::Field, Nodes::Field, bool) -> void
    def check_merge a, b, exclusive
      return if a.equal?(b)

      # Fragments spread in many places compare the same pairs many times.
      # Checking a pair as not exclusive also checks it as exclusive
      first, second = a.start <= b.start ? [a, b] : [b, a]
      checked = @merged[first] ||= {}.compare_by_identity
      previous = checked[second]
      return if previous == false || (previous && exclusive)
      checked[second] = exclusive

      key = b.aliaz || b.name
      parent_a = a.parent_type
      parent_b = b.parent_type
      exclusive ||= parent_a != parent_b && !abstract_possible_types(parent_a) && !abstract_possible_types(parent_b)
      unless exclusive
        if a.name != b.name
          validation_error! "Fields #{key} conflict because #{a.name} and #{b.name} are different fields", b.start
        end
        unless same_arguments?(a.arguments, b.arguments)
          validation_error! "Fields #{key} conflict because they have differing arguments", b.start
        end
      end

      type_a = field_type(parent_a, a.name)
      type_b = field_type(parent_b, b.name)
      return_type_conflict key, a, type_a, b, type_b unless same_response_shape?(type_a, type_b)

      set_a = a.selection_set
      set_b = b.selection_set
      return unless set_a && set_b

      fields_a = merged_fields(set_a)
      fields_b = merged_fields(set_b)
      keys = fields_a.keys
      i = 0
      while i < keys.length
        if (others = fields_b[keys[i]])
          check_merges fields_a[keys[i]], others, exclusive
        end
        i += 1
      end
    end

    # Checks each field in `mine` against each field in `others`.  Each is
    # a field or an Array of fields with the same response key
    #: (Nodes::Field | Array[Nodes::Field], Nodes::Field | Array[Nodes::Field], bool) -> void
    def check_merges mine, others, exclusive
      if mine.is_a?(Array)
        j = 0
        while j < mine.length
          check_merges mine[j], others, exclusive
          j += 1
        end
      elsif others.is_a?(Array)
        k = 0
        while k < others.length
          check_merge mine, others[k], exclusive
          k += 1
        end
      else
        check_merge mine, others, exclusive
      end
    end

    # Whether fields of types `a` and `b` give values of the same shape.
    # Their children are checked separately
    #: (Nodes::NamedType | Nodes::ListType | Nodes::NotNullType, Nodes::NamedType | Nodes::ListType | Nodes::NotNullType) -> bool
    def same_response_shape? a, b
      while true
        if a.not_null_type? || b.not_null_type?
          return false unless a.not_null_type? && b.not_null_type?
          a = a.type
          b = b.type
        elsif a.list_type? || b.list_type?
          return false unless a.list_type? && b.list_type?
          a = a.type
          b = b.type
        elsif composite_type?(a.name) || composite_type?(b.name)
          return composite_type?(a.name) && composite_type?(b.name)
        else
          return a.name == b.name
        end
      end
    end

    # Whether two fields' arguments are the same, in any order
    #: (Array[Nodes::Argument]?, Array[Nodes::Argument]?) -> bool
    def same_arguments? a, b
      return (a.nil? || a.empty?) && (b.nil? || b.empty?) if a.nil? || b.nil?
      return false unless a.length == b.length
      i = 0
      while i < a.length
        argument = a[i]
        j = 0
        j += 1 while j < b.length && b[j].name != argument.name
        return false unless j < b.length && same_value?(argument.value, b[j].value)
        i += 1
      end
      true
    end

    # Whether two values are written the same.  Input object fields may be
    # in any order
    #: (Nodes::Value | Nodes::ObjectValue | Nodes::Variable, Nodes::Value | Nodes::ObjectValue | Nodes::Variable) -> bool
    def same_value? a, b
      return false unless a.class == b.class

      if a.variable?
        a.name == b.name
      elsif a.object_value?
        fields_a = a.values
        fields_b = b.values
        return false unless fields_a.length == fields_b.length
        i = 0
        while i < fields_a.length
          field = fields_a[i]
          j = 0
          j += 1 while j < fields_b.length && fields_b[j].name != field.name
          return false unless j < fields_b.length && same_value?(field.value, fields_b[j].value)
          i += 1
        end
        true
      elsif a.list_value?
        items_a = a.value
        items_b = b.value
        return false unless items_a.length == items_b.length
        i = 0
        while i < items_a.length
          return false unless same_value?(items_a[i], items_b[i])
          i += 1
        end
        true
      else
        a.value == b.value
      end
    end

    #: (Integer) -> Integer
    def lowest_bit bits
      (bits & -bits).bit_length - 1
    end

    #: (Nodes::OperationDefinition) -> String
    def operation_label operation
      operation.name ? " by operation #{operation.name}" : ""
    end

    # Whether a variable may be used where `location` is expected.  A
    # nullable variable with a default may be used for a non-null type,
    # because the default is used when the variable is missing
    #: (Nodes::VariableDefinition, Nodes::NamedType | Nodes::ListType | Nodes::NotNullType) -> bool
    def variable_allowed? definition, location
      type = definition.type
      if location.not_null_type? && !type.not_null_type?
        default = definition.default_value
        return false if default.nil? || default.null_value?
        location = location.type
      end
      types_compatible?(type, location)
    end

    # Whether a variable of `type` fits `location`, both type nodes
    #: (Nodes::NamedType | Nodes::ListType | Nodes::NotNullType, Nodes::NamedType | Nodes::ListType | Nodes::NotNullType) -> bool
    def types_compatible? type, location
      while true
        if location.not_null_type?
          return false unless type.not_null_type?
          type = type.type
          location = location.type
        elsif type.not_null_type?
          type = type.type
        elsif location.list_type?
          return false unless type.list_type?
          type = type.type
          location = location.type
        elsif type.list_type?
          return false
        else
          return type.name == location.name
        end
      end
    end

    #: (Nodes::NamedType | Nodes::ListType | Nodes::NotNullType) -> String
    def type_string type
      if type.list_type?
        "[#{type_string(type.type)}]"
      elsif type.not_null_type?
        "#{type_string(type.type)}!"
      else
        type.name
      end
    end

    # A fragment on `type` may only be spread into `parent` when some object
    # could be both
    #: (String, String, Integer) -> void
    def check_spread type, parent, loc
      return if type == parent
      validation_error!("Unknown type #{type}", loc) unless composite_type?(type)

      types = abstract_possible_types(type)
      parent_types = abstract_possible_types(parent)

      overlap = if types && parent_types
        types.anybits?(parent_types)
      elsif types
        # `parent` is an object type, check whether it's one of `type`'s
        bit = object_bit(parent)
        bit && types[bit] == 1
      elsif parent_types
        bit = object_bit(type)
        bit && parent_types[bit] == 1
      else
        # Two different object types never overlap
        false
      end

      unless overlap
        validation_error! "Fragment on #{type} can never apply to #{parent}", loc
      end
    end

    # Called when fields `a` and `b`, with response key `key`, return
    # values of different shapes, like String and Image!.  The spec doesn't
    # allow this even when the fields are on different object types, so
    # this raises ValidationError.  Override it in a subclass to accept
    # these documents anyway, like graphql-ruby's
    # `allow_legacy_invalid_return_type_conflicts`.  The executor only
    # includes fields whose fragments apply to each object, so it returns
    # the right data for them when the fields are mutually exclusive
    #
    #   class RecordingParser < MyParser
    #     attr_reader :conflicts
    #
    #     def initialize doc, scalars: Scalars.new
    #       super
    #       @conflicts = []
    #     end
    #
    #     private def return_type_conflict(key, a, type_a, b, type_b)
    #       @conflicts << key
    #     end
    #   end
    #
    #   parser = RecordingParser.new(query)
    #   doc = parser.parse
    #   parser.conflicts # => ["icon"]
    #: (String, Nodes::Field, Nodes::NamedType | Nodes::ListType | Nodes::NotNullType, Nodes::Field, Nodes::NamedType | Nodes::ListType | Nodes::NotNullType) -> void
    def return_type_conflict key, a, type_a, b, type_b
      validation_error! "Fields #{key} conflict because they return conflicting types #{type_string type_a} and #{type_string type_b}", b.start
    end

    #: (String, Integer) -> bot
    def unknown_type! type, loc
      validation_error! "Unknown type #{type}", loc
    end

    #: (String) -> bot
    def unsupported_operation! type
      validation_error! "Schema does not support #{type} operations", pos
    end

    #: (String, String, Integer) -> bot
    def unknown_field! name, parent, loc
      validation_error! "Field #{name} does not exist on #{parent}", loc
    end

    #: (String, String, Integer) -> bot
    def leaf_selection_set! name, parent, loc
      validation_error! "Field #{parent}.#{name} cannot have a selection set", loc
    end

    #: (String, String, Integer) -> bot
    def missing_selection_set! name, parent, loc
      validation_error! "Field #{parent}.#{name} must have a selection set", loc
    end

    #: (String, String, String, Integer) -> bot
    def unknown_argument! name, field, parent, loc
      validation_error! "Unknown argument #{name} on #{parent}.#{field}", loc
    end

    #: (String, String, String, Integer) -> bot
    def missing_argument! name, field, parent, loc
      validation_error! "Missing required argument #{name} on #{parent}.#{field}", loc
    end

    #: (String, String, String, Integer) -> bot
    def duplicate_argument! name, field, parent, loc
      validation_error! "Duplicate argument #{name} on #{parent}.#{field}", loc
    end

    #: (String, String, String, String, Integer) -> bot
    def invalid_argument! name, field, parent, message, loc
      validation_error! "Invalid value for argument #{name} on #{parent}.#{field}: #{message}", loc
    end

    # Custom scalars accept any literal.  Generated parsers parse one in
    # three steps, calling the scalar's coerce_literal_X method between the
    # last two:
    #
    #   kind = custom_literal_kind
    #   text = custom_literal_text kind, "DateTime"
    #   custom_literal loc, kind, text, @scalars.coerce_literal_DateTime(kind, text)

    # The kind of literal at the current token, without consuming it
    #: () -> Symbol
    def custom_literal_kind
      case token_name
      when :INT then :INT
      when :FLOAT then :FLOAT
      when :STRING then :STRING
      when :TRUE, :FALSE then :BOOLEAN
      when :IDENTIFIER, *ENUM_VALUE_KEYWORD_TOKENS then :ENUM
      when :LBRACKET then :LIST
      when :LCURLY then :OBJECT
      else
        # Not a value, so this raises like the generic parser does
        value
      end
    end

    # Consumes a literal of `kind` and returns its text, or the parsed node
    # for lists and objects
    #: (Symbol, String) -> (String | Nodes::ListValue | Nodes::ObjectValue)
    def custom_literal_text kind, scalar
      case kind
      when :STRING then expect_string_value
      when :LIST, :OBJECT then const_value(scalar)
      else expect_token_value(token_name)
      end
    end

    # The node for a literal of `kind`, with its coerced value deeply frozen
    #: (Integer, Symbol, (String | Nodes::ListValue | Nodes::ObjectValue), untyped) -> (Nodes::Value | Nodes::ObjectValue | Nodes::Variable)
    def custom_literal loc, kind, text, coerced
      coerced = Ractor.make_shareable(coerced)
      case kind
      when :INT then Nodes::IntValue.new(loc, text, coerced)
      when :FLOAT then Nodes::FloatValue.new(loc, text, coerced)
      when :STRING then Nodes::StringValue.new(loc, text, coerced)
      when :BOOLEAN then Nodes::BooleanValue.new(loc, text, coerced)
      when :ENUM then Nodes::EnumValue.new(loc, text, coerced)
      when :LIST then Nodes::ListValue.new(loc, text.value, coerced)
      when :OBJECT then Nodes::ObjectValue.new(loc, text.values, coerced)
      end
    end

    # Parses a value that can't contain variables.  Custom scalars that
    # accept list and object literals get the whole literal, which has to be
    # known at parse time so it can be coerced
    #
    #: (String) -> (Nodes::Value | Nodes::ObjectValue | Nodes::Variable)
    def const_value scalar
      case token_name
      when :VAR_SIGN
        raise Scalars::InvalidValue, "Variables can't be used inside #{scalar} literals"
      when :LBRACKET
        loc = pos
        accept_token
        items = []
        items << const_value(scalar) while !at?(:RBRACKET)
        accept_token
        Nodes::ListValue.new(loc, items.freeze, nil)
      when :LCURLY
        loc = pos
        accept_token
        fields = []
        while !at?(:RCURLY)
          field_loc = pos
          name = self.name
          expect_token :COLON
          fields << Nodes::ObjectField.new(field_loc, name, const_value(scalar))
        end
        accept_token
        Nodes::ObjectValue.new(loc, fields.freeze, nil)
      else
        value
      end
    end

    # Value checks raise InvalidValue, and the argument method that called
    # them reports which argument was invalid

    LITERAL_ERRORS = {
      "Int" => "Int cannot represent non-integer value",
      "Float" => "Float cannot represent non numeric value",
      "String" => "String cannot represent a non string value",
      "Boolean" => "Boolean cannot represent a non boolean value",
      "ID" => "ID cannot represent a non-string and non-integer value",
    }.freeze #: Hash[String, String]

    # A literal of the wrong kind for built in scalar `type`
    #: (String, Nodes::Value | Nodes::ObjectValue | Nodes::Variable) -> bot
    def invalid_literal! type, node
      raise Scalars::InvalidValue, "#{LITERAL_ERRORS.fetch(type)}: #{Scalars.describe node}"
    end

    #: (String) -> bot
    def null_value! type
      raise Scalars::InvalidValue, "Expected value of type #{type}, found null"
    end

    #: (String, String) -> bot
    def unknown_enum_value! type, name
      raise Scalars::InvalidValue, "Value #{name} does not exist in #{type} enum"
    end

    #: (String, Nodes::Value | Nodes::ObjectValue | Nodes::Variable) -> bot
    def invalid_enum! type, node
      raise Scalars::InvalidValue, "Enum #{type} cannot represent non-enum value: #{Scalars.describe node}"
    end

    #: (String, Nodes::Value | Nodes::ObjectValue | Nodes::Variable) -> bot
    def unexpected_value! type, node
      raise Scalars::InvalidValue, "Expected value of type #{type}, found #{Scalars.describe node}"
    end

    #: (String, String) -> bot
    def unknown_input_field! name, type
      raise Scalars::InvalidValue, "Field #{name} is not defined by type #{type}"
    end

    #: (String) -> bot
    def duplicate_input_field! name
      raise Scalars::InvalidValue, "There can be only one input field named #{name}"
    end

    #: (String, String, String) -> bot
    def missing_input_field! name, type, field_type
      raise Scalars::InvalidValue, "Field #{type}.#{name} of required type #{field_type} was not provided"
    end

    # Parses the rest of a field that has no arguments and no selection set.
    # This is the most common kind of field, so sharing it keeps generated
    # parsers smaller
    #: (Integer, String?, String, String) -> Nodes::Field
    def leaf_field loc, aliaz, name, parent
      no_arguments! name, parent
      directives = if at?(:DIR_SIGN); self.directives; end
      leaf_selection_set! name, parent, loc if at?(:LCURLY)
      Nodes::Field.new(loc, aliaz, name, nil, directives, nil, parent)
    end

    # Raises if the field being parsed has arguments.  For fields that don't
    # take any
    #: (String, String) -> void
    def no_arguments! field, parent
      return unless at?(:LPAREN)
      accept_token
      loc = pos
      unknown_argument! name, field, parent, loc
    end

    #: (String, Integer) -> bot
    def validation_error! message, loc
      line = @doc.byteslice(0, loc).count("\n") + 1
      raise ValidationError, "#{message} line: #{line}"
    end
  end
end
